begin;
alter table public.profiles add column if not exists candidate_profile jsonb not null default '{}'::jsonb check (jsonb_typeof(candidate_profile) = 'object');
create table if not exists public.saved_jobs (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, title text not null, company text, location text, description text not null, url text, source text, status text not null default 'saved' check (status in ('saved','archived','applied')), fit_analysis jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.applications (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, job_id uuid not null references public.saved_jobs(id) on delete cascade, status text not null default 'draft' check (status in ('draft','ready','submitted','withdrawn','rejected','interviewing','offer')), notes text, drafts jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id, job_id));
create table if not exists public.application_events (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, application_id uuid not null references public.applications(id) on delete cascade, event_type text not null, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create index if not exists saved_jobs_user_created on public.saved_jobs(user_id, created_at desc); create index if not exists applications_user_updated on public.applications(user_id, updated_at desc); create index if not exists application_events_application on public.application_events(application_id, created_at desc);
alter table public.saved_jobs enable row level security; alter table public.applications enable row level security; alter table public.application_events enable row level security;
create policy saved_jobs_own on public.saved_jobs for all to authenticated using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
create policy applications_own on public.applications for all to authenticated using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
create policy application_events_own on public.application_events for all to authenticated using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
revoke all on public.saved_jobs, public.applications, public.application_events from public, anon, authenticated; grant select,insert,update,delete on public.saved_jobs, public.applications, public.application_events to authenticated; grant all on public.saved_jobs, public.applications, public.application_events to service_role;
commit;
